window.CaseLearningGuide={"id":"edu08-d3-trajectory-control","title":"井眼轨迹智能控制","method":"学习状态转移代理＋两步模型预测控制","what":"线性回归学习下一状态，用两步动作枚举实现有限时域反馈控制。","why":"学习状态转移作为短期代理，再枚举控制序列，展示预测控制的反馈过程。","how":"135条训练转移学习动力响应，45条独立转移核对；每步搜索49个动作序列，只执行首动作，然后读取新状态重新搜索。","limit":"全部数据与工况为教学合成或虚构。评价只描述当前合成机制下的表现。本例不直接生成现场设计、控制或处置指令。","trial":"提高扰动和控制代价，比较预测控制与固定比例控制的偏差。","inputs":["当前井斜偏差","工具面控制量","地层扰动"],"output":"下一步轨迹偏差","type":"control","before":"固定动作难兼顾扰动变化和动作代价。","benefit":"预测未来几步再反馈，轨迹与动作曲线清楚显示控制取舍。","controls":["cost","disturbance"],"views":[{"name":"状态轨迹与反馈基线","selector":"#main-chart"},{"name":"当前控制动作","selector":"#analysis-chart"},{"name":"一步代理预测","selector":"#evaluation-chart"}],"steps":[{"name":"生成状态转移样本","do":"135条转移训练、45条独立转移测试，不用评价轨迹反向拟合。","effect":"所有状态与动作都是归一教学量。"},{"name":"学习下一状态","do":"用当前状态、动作和扰动预测下一状态。","effect":"合成系统推进轨迹，代理负责预测，两者分别实现。"},{"name":"构造两步候选","do":"枚举7×7种动作组合，按代理预测未来两步状态。","effect":"预测范围有限，不能等同全局最优控制。"},{"name":"筛约束并执行首步","do":"筛教学状态约束，最小化状态偏差与动作惩罚；只执行第一步。","effect":"无可行候选时采用零调整并保留状态。"},{"name":"同扰动比较策略","do":"同一合成系统、初始状态与扰动下比较35步轨迹。","effect":"基线与学习控制使用相同评价条件。"},{"name":"改变扰动与代价","do":"提高动作惩罚或扰动，检查轨迹和控制动作变化。","effect":"实际方法是预测控制，不将它称为强化学习。"}]};
